import java.util.*;

public class ZigzagIterator {
  private final Deque<Iterator<Integer>> queue = new ArrayDeque<>();

  public ZigzagIterator(List<Integer> v1, List<Integer> v2) {
    if (!v1.isEmpty()) queue.add(v1.iterator());
    if (!v2.isEmpty()) queue.add(v2.iterator());
  }

  public int next() {
    // take from the front list, then send it to the back if it still has elements (works for k lists too)
    Iterator<Integer> it = queue.poll();
    int v = it.next();
    if (it.hasNext()) queue.add(it);
    return v;
  }

  public boolean hasNext() {
    return !queue.isEmpty();
  }
}
